1	"use client";
2	
3	import Link from "next/link";
4	import { useRouter } from "next/navigation";
5	import { useEffect, useRef, useState, useSyncExternalStore } from "react";
6	import { ArrowUp, Paperclip, Mic, X, Gift, Sparkles } from "lucide-react";
7	import { motion, useReducedMotion } from "framer-motion";
8	import { PENDING_PROMPT_KEY, PENDING_PROMPT_IMAGE_KEY } from "@/lib/pending-prompt";
9	import { SIGNUP_GRANT } from "@/lib/credits";
10	
11	// The rotating gradient inside each glow clip MUST be a square that is
12	// larger than the clip's diagonal, or it stops covering the clip partway
13	// through its own rotation and the ring visibly vanishes and returns on a
14	// loop. (The previous `inset-[-50%]` made it 2x the clip in BOTH axes —
15	// e.g. 1372x296 for this wide composer. Rotated 90deg that occupies
16	// 296x1372: only 296px wide, far short of the ~686px the clip needs
17	// covered. Hence "the glow keeps disappearing.")
18	//
19	// 200% width + aspectRatio 1 gives a square of side 2*clipWidth, which
20	// always exceeds the diagonal. Centering uses margins rather than a
21	// translate because `transform` is owned by the rotation keyframes and a
22	// transform in the animation would override any translate set here —
23	// percentage margins (all sides, per spec) resolve against the containing
24	// block's WIDTH, so -100% on both axes lands the square's center exactly
25	// on the clip's center.
26	const SPIN_SQUARE: React.CSSProperties = {
27	  position: "absolute",
28	  left: "50%",
29	  top: "50%",
30	  width: "200%",
31	  aspectRatio: "1",
32	  marginLeft: "-100%",
33	  marginTop: "-100%",
34	};
35	
36	const SUGGESTIONS = [
37	  "A portfolio site for a freelance photographer",
38	  "A landing page for my SaaS product",
39	  "A website for a neighborhood coffee shop",
40	  "A booking page for my consulting practice",
41	];
42	
43	// Downscale + re-encode client-side so a phone photo doesn't blow past
44	// sessionStorage's per-origin quota (or the tokens it costs Claude to look
45	// at it) — a reference image only needs to be legible, not full-resolution.
46	async function downscaleImage(file: File, maxDim = 1400, quality = 0.82): Promise<string> {
47	  const bitmap = await createImageBitmap(file);
48	  const scale = Math.min(1, maxDim / Math.max(bitmap.width, bitmap.height));
49	  const w = Math.round(bitmap.width * scale);
50	  const h = Math.round(bitmap.height * scale);
51	  const canvas = document.createElement("canvas");
52	  canvas.width = w;
53	  canvas.height = h;
54	  const ctx = canvas.getContext("2d");
55	  if (!ctx) throw new Error("canvas unsupported");
56	  ctx.drawImage(bitmap, 0, 0, w, h);
57	  return canvas.toDataURL("image/jpeg", quality);
58	}
59	
60	// The Web Speech API has no types in TypeScript's DOM lib, so this is a
61	// minimal hand-written shim covering exactly the surface used below —
62	// narrower than the real spec on purpose, so it can't quietly drift into
63	// asserting support for members this component never touches.
64	type SpeechRecognitionAlternativeLike = { readonly transcript: string };
65	type SpeechRecognitionResultLike = {
66	  readonly length: number;
67	  readonly [index: number]: SpeechRecognitionAlternativeLike;
68	};
69	type SpeechRecognitionEventLike = {
70	  readonly results: {
71	    readonly length: number;
72	    readonly [index: number]: SpeechRecognitionResultLike;
73	  };
74	};
75	type SpeechRecognitionLike = {
76	  continuous: boolean;
77	  interimResults: boolean;
78	  lang: string;
79	  start: () => void;
80	  stop: () => void;
81	  onresult: ((e: SpeechRecognitionEventLike) => void) | null;
82	  onend: (() => void) | null;
83	  onerror: (() => void) | null;
84	};
85	type SpeechRecognitionCtor = new () => SpeechRecognitionLike;
86	
87	// Narrowed locally rather than via `declare global`: augmenting Window would
88	// collide with the (differently-shaped) definitions any future TS DOM lib
89	// ships for this API.
90	type SpeechCapableWindow = {
91	  SpeechRecognition?: SpeechRecognitionCtor;
92	  webkitSpeechRecognition?: SpeechRecognitionCtor;
93	};
94	
95	function getSpeechRecognition(): SpeechRecognitionCtor | null {
96	  if (typeof window === "undefined") return null;
97	  const w = window as unknown as SpeechCapableWindow;
98	  return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
99	}
100	
101	// Feature detection is *external* state: it is unknowable while rendering on
102	// the server, and rendering the mic button in the server HTML would be a
103	// hydration mismatch. useSyncExternalStore is the sanctioned way to express
104	// that — getServerSnapshot() feeds both SSR and the hydration render, and
105	// React re-reads getSnapshot() only once hydration has finished. Support
106	// never changes within a page's life, so subscribe is a no-op.
107	const NEVER_CHANGES = () => () => {};
108	const readSpeechSupported = () => getSpeechRecognition() !== null;
109	const speechUnsupportedOnServer = () => false;
110	
111	export function PromptHero() {
112	  const router = useRouter();
113	  const reduced = useReducedMotion();
114	  const [value, setValue] = useState("");
115	  const [focused, setFocused] = useState(false);
116	  const [image, setImage] = useState<string | null>(null);
117	  const [listening, setListening] = useState(false);
118	  const speechSupported = useSyncExternalStore(
119	    NEVER_CHANGES,
120	    readSpeechSupported,
121	    speechUnsupportedOnServer,
122	  );
123	  const [enhanceSupported, setEnhanceSupported] = useState(false);
124	  const [enhancing, setEnhancing] = useState(false);
125	  // The prompt as typed, kept only while an enhanced spec is on screen — this
126	  // is what "Revert" restores, and its presence is what tells the composer it
127	  // is currently showing a spec rather than a one-liner.
128	  const [enhancedFrom, setEnhancedFrom] = useState<string | null>(null);
129	  const [enhanceError, setEnhanceError] = useState<string | null>(null);
130	  const fileInputRef = useRef<HTMLInputElement>(null);
131	  const recognitionRef = useRef<SpeechRecognitionLike | null>(null);
132	  const baseValueRef = useRef("");
133	
134	  // /api/enhance is auth-gated, and most people meeting this hero are signed
135	  // out — so the button appears only once we know it would work, the same way
136	  // the mic waits on feature detection above. Failing closed is the point:
137	  // an affordance that 401s on click is worse than no affordance.
138	  useEffect(() => {
139	    let alive = true;
140	    fetch("/api/auth/me")
141	      .then((res) => res.json())
142	      .then((body) => {
143	        if (alive && body?.user) setEnhanceSupported(true);
144	      })
145	      .catch(() => {});
146	    return () => {
147	      alive = false;
148	    };
149	  }, []);
150	
151	  async function enhance() {
152	    const text = value.trim();
153	    if (!text || enhancing) return;
154	
155	    setEnhancing(true);
156	    setEnhanceError(null);
157	    try {
158	      const res = await fetch("/api/enhance", {
159	        method: "POST",
160	        headers: { "Content-Type": "application/json" },
161	        // Always the ORIGINAL one-liner, never a spec we already produced —
162	        // enhancing an enhancement compounds invention instead of adding
163	        // detail, and the round trip would drift further from what was asked.
164	        body: JSON.stringify({ prompt: enhancedFrom ?? text }),
165	      });
166	      const body = await res.json().catch(() => ({}));
167	      if (!res.ok || !body?.spec) throw new Error(body?.error ?? "Couldn't expand that.");
168	      setEnhancedFrom(enhancedFrom ?? text);
169	      setValue(body.spec);
170	    } catch (err) {
171	      // Nothing is destroyed on failure: `value` still holds what they typed,
172	      // and the build button beside this was never disabled.
173	      setEnhanceError(err instanceof Error ? err.message : "Couldn't expand that.");
174	    } finally {
175	      setEnhancing(false);
176	    }
177	  }
178	
179	  function revert() {
180	    if (enhancedFrom === null) return;
181	    setValue(enhancedFrom);
182	    setEnhancedFrom(null);
183	    setEnhanceError(null);
184	  }
185	
186	  function submit() {
187	    const text = value.trim();
188	    if (!text) return;
189	    try {
190	      sessionStorage.setItem(PENDING_PROMPT_KEY, text);
191	      if (image) sessionStorage.setItem(PENDING_PROMPT_IMAGE_KEY, image);
192	      else sessionStorage.removeItem(PENDING_PROMPT_IMAGE_KEY);
193	    } catch {}
194	    router.push("/signup");
195	  }
196	
197	  async function onPickImage(e: React.ChangeEvent<HTMLInputElement>) {
198	    const file = e.target.files?.[0];
199	    e.target.value = "";
200	    if (!file || !file.type.startsWith("image/")) return;
201	    try {
202	      setImage(await downscaleImage(file));
203	    } catch {}
204	  }
205	
206	  function toggleListening() {
207	    const Ctor = getSpeechRecognition();
208	    if (!Ctor) return;
209	
210	    if (listening) {
211	      recognitionRef.current?.stop();
212	      return;
213	    }
214	
215	    const rec = new Ctor();
216	    rec.continuous = true;
217	    rec.interimResults = true;
218	    rec.lang = "en-US";
219	    baseValueRef.current = value ? value.trim() + " " : "";
220	
221	    rec.onresult = (e: SpeechRecognitionEventLike) => {
222	      let transcript = "";
223	      for (let i = 0; i < e.results.length; i++) transcript += e.results[i][0].transcript;
224	      setValue((baseValueRef.current + transcript).trimStart());
225	    };
226	    rec.onend = () => setListening(false);
227	    rec.onerror = () => setListening(false);
228	
229	    recognitionRef.current = rec;
230	    rec.start();
231	    setListening(true);
232	  }
233	
234	  useEffect(() => () => recognitionRef.current?.stop(), []);
235	
236	  return (
237	    <div className="relative mx-auto w-full max-w-2xl">
238	      {/* Free-credits badge — the first thing a visitor should register
239	          about pricing, before they've even typed anything. Sits above the
240	          glow/composer group entirely (not inside its relative wrapper) so
241	          the glow below hugs just the box, not the badge too. */}
242	      <div className="mb-4 flex justify-center">
243	        <span className="inline-flex items-center gap-1.5 rounded-full border border-neutral-200/70 bg-white/60 px-3.5 py-1.5 text-xs font-medium text-neutral-600 backdrop-blur-md dark:border-white/10 dark:bg-white/[0.05] dark:text-neutral-300">
244	          <Gift size={13} style={{ color: "var(--accent)" }} />
245	          Get {SIGNUP_GRANT} free credits — enough for a real site and a few edits
246	        </span>
247	      </div>
248	
249	      {/* This inner wrapper is sized to exactly the composer box — the glow
250	          layers below position with -inset-N relative to IT specifically,
251	          not the outer component (which also holds the badge and suggestion
252	          chips), so the glow hugs just the box, never the whole component. */}
253	      <div className="relative">
254	      {/* The glow — a Gemini-style "chasing light" ring, rebuilt with only
255	          plain `transform: rotate()` + `overflow: hidden` clipping — no
256	          @property, no CSS masking (dropped after those didn't visibly
257	          work even in a fresh, verified non-cached browser). Two layers:
258	          a thin bright one (-inset-[7px]) and a soft blurred halo
259	          (-inset-[22px]). Deliberately NOT the page's big ambient .aura
260	          blobs (Aura.tsx), a separate, much larger, static effect.
261	
262	          The blur lives on the CLIP element, not on the rotating child.
263	          That ordering matters: filters apply AFTER the element (and its
264	          overflow:hidden clipping) is rendered, so the blur softens the
265	          clip's hard outer cutoff and lets the light bleed beyond the
266	          clip's bounds — a real falloff. With the blur on the child
267	          instead, the clip's crisp edge survives and the result reads as
268	          a chunky solid border rather than a glow.
269	
270	          Each layer's blur radius therefore wants to be comparable to or
271	          larger than its own inset, so the band never looks like a hard
272	          stripe. Opacities are deliberately well under 1 (see
273	          glow-fade-in-a/-b) — at full strength the brand colors read as a
274	          saturated ring instead of ambient light.
275	
276	          Each layer is a STATIC outer clipper (glow-clip-*, overflow:
277	          hidden, never transforms) containing one OVERSIZED inner
278	          rotator (glow-spin-*, ~2x the clipper's size via inset:-50%,
279	          centered). Only the inner rotator spins — being oversized, its
280	          corners sweeping outside a same-sized box (the original "wide
281	          rectangle rotated as a rigid body swings outside its footprint"
282	          bug) never matters, since the static outer box clips them away
283	          at every angle. The opaque composer sitting on top (z-10) covers
284	          the rotator's entire interior on its own, leaving only the outer
285	          few px visible as a ring — no masking needed for that either.
286	
287	          Opacity is fixed, not keyed off `focused` — an earlier version
288	          dimmed on blur, which read as "disappearing." The composer's own
289	          border/shadow below is the right place for a focus affordance;
290	          this ambient ring stays constant.
291	
292	          Entrance: fade+scale in once via the glow-fade-in-a/-b keyframes
293	          on the outer clipper (globals.css) — plain CSS, not a
294	          framer-motion `whileInView`.
295	
296	          NO NEGATIVE Z-INDEX HERE — this was the "it appears for a moment
297	          on load, then is gone for good" bug. PromptHero is wrapped in
298	          <Reveal>, which animates opacity 0 -> 1. An element with opacity
299	          BETWEEN 0 and 1 establishes a stacking context, which kept these
300	          layers painting above the page background while the reveal ran.
301	          The moment opacity reached exactly 1 that stacking context was
302	          destroyed, and `-z-10` dropped the layers behind the root page
303	          div's opaque bg-white / dark:bg-neutral-950 — invisible, forever.
304	          Instead the layers now sit at the default level (painting above
305	          the page background) and the composer is lifted above THEM with
306	          z-10, which needs no stacking-context trickery to hold. */}
307	      <div aria-hidden className="glow-clip-a pointer-events-none absolute -inset-[3px] overflow-hidden rounded-[1.9rem] blur-[5px]">
308	        <div
309	          className="glow-spin-a"
310	          style={{
311	            ...SPIN_SQUARE,
312	            // Stops are pushed into distinct quadrants (rather than the
313	            // near-adjacent pink/coral/orange run they used to be) so the
314	            // colour visibly travels around the box as this rotates —
315	            // closely-spaced hues just blur into one flat pink.
316	            background:
317	              "conic-gradient(#f72570 0deg, #a33dff 90deg, #ff9868 180deg, #ff6b67 270deg, #f72570 360deg)",
318	          }}
319	        />
320	      </div>
321	      <div aria-hidden className="glow-clip-b pointer-events-none absolute -inset-[14px] overflow-hidden rounded-[2.4rem] blur-[22px]">
322	        <div
323	          className="glow-spin-b"
324	          style={{
325	            ...SPIN_SQUARE,
326	            background:
327	              "conic-gradient(from 180deg, #a33dff 0deg, #f72570 90deg, #ff9868 180deg, #ff6b67 270deg, #a33dff 360deg)",
328	          }}
329	        />
330	      </div>
331	
332	      {/* The glass composer. Opaque enough that the animated ring behind it
333	          (see above) reads as a halo around the box, not a wash bleeding
334	          through onto the text — earlier versions were translucent enough
335	          that the strong glow behind showed straight through onto the
336	          placeholder/input text. Still picks up a faint frosted quality from
337	          backdrop-blur, just not at the cost of legibility. */}
338	      <div
339	        className="relative z-10 overflow-hidden rounded-[1.75rem] bg-white/95 backdrop-blur-2xl backdrop-saturate-150 transition-colors duration-300 dark:bg-neutral-950/95"
340	        style={{
341	          // No focus-driven glow here — the animated ring behind the box is
342	          // the only glow, and a second one on focus fought with it. Focus
343	          // is still signalled (it must be, for keyboard users) but with a
344	          // quiet border shift instead.
345	          border: `1.5px solid ${
346	            focused
347	              ? "color-mix(in srgb, white 45%, var(--accent) 55%)"
348	              : "color-mix(in srgb, white 75%, var(--accent) 25%)"
349	          }`,
350	          boxShadow: "var(--sh-s), inset 0 1px 0 rgba(255,255,255,0.5)",
351	        }}
352	      >
353	        {image && (
354	          <div className="flex items-center gap-2 px-6 pt-4">
355	            <div className="relative h-12 w-12 overflow-hidden rounded-lg border border-black/10 dark:border-white/10">
356	              {/* eslint-disable-next-line @next/next/no-img-element */}
357	              <img src={image} alt="Attached reference" className="h-full w-full object-cover" />
358	              <button
359	                type="button"
360	                onClick={() => setImage(null)}
361	                aria-label="Remove attached image"
362	                className="absolute right-0.5 top-0.5 flex h-4 w-4 items-center justify-center rounded-full bg-black/60 text-white"
363	              >
364	                <X size={10} strokeWidth={3} />
365	              </button>
366	            </div>
367	            <span className="text-xs text-neutral-500 dark:text-neutral-400">Reference image attached</span>
368	          </div>
369	        )}
370	
371	        {/* The spec is not a modal or a preview pane — it lands straight in the
372	            composer's own textarea, which is already editable and already the
373	            thing the send button reads. So "accept" is just pressing send,
374	            "edit" is typing, and "discard" is Revert. No new pattern, and no
375	            state where the user is stuck looking at something they can't
376	            change. */}
377	        {enhancedFrom !== null && (
378	          <div className="flex items-center justify-between gap-2 px-6 pt-4">
379	            <span className="inline-flex items-center gap-1.5 text-xs text-neutral-500 dark:text-neutral-400">
380	              <Sparkles size={13} style={{ color: "var(--accent)" }} />
381	              Expanded spec — edit anything before you build
382	            </span>
383	            <button
384	              type="button"
385	              onClick={revert}
386	              className="text-xs text-neutral-500 underline underline-offset-2 transition-colors hover:text-neutral-900 dark:text-neutral-400 dark:hover:text-white"
387	            >
388	              Revert
389	            </button>
390	          </div>
391	        )}
392	
393	        {/* role="alert" so a failed Enhance is spoken rather than appearing
394	            silently above a textarea the user is looking away from. */}
395	        {enhanceError && (
396	          <p role="alert" className="px-6 pt-4 text-xs text-neutral-500 dark:text-neutral-400">
397	            {enhanceError}
398	          </p>
399	        )}
400	
401	        {/* The placeholder was the only label, and it disappears on the first
402	            keystroke. A visible one would change the design, so this is a
403	            sr-only label tied to the field by id. */}
404	        <label htmlFor="prompt-hero-input" className="sr-only">
405	          Describe the site you want to build
406	        </label>
407	        <textarea
408	          id="prompt-hero-input"
409	          value={value}
410	          onChange={(e) => setValue(e.target.value)}
411	          onFocus={() => setFocused(true)}
412	          onBlur={() => setFocused(false)}
413	          onKeyDown={(e) => {
414	            // Enter sends a one-liner, but while a spec is on screen this box
415	            // is a multi-line editor — there, Enter has to make a newline or
416	            // the first paragraph break the user types starts a build of a
417	            // half-edited spec. The send button still works either way.
418	            if (e.key === "Enter" && !e.shiftKey && enhancedFrom === null) {
419	              e.preventDefault();
420	              submit();
421	            }
422	          }}
423	          // A ~200-word spec in a two-row box is unreviewable, and an
424	          // unreviewed spec defeats the whole feature — grow to fit it.
425	          rows={enhancedFrom !== null ? 12 : 2}
426	          placeholder={listening ? "Listening…" : "Describe the site you want to build…"}
427	          // `outline-none` left the composer's own border shift as the only
428	          // focus signal, and that shift (a 25% -> 55% accent tint of white)
429	          // is about 1.5:1 against its own unfocused state — under the 3:1
430	          // WCAG 2.4.11 asks of a focus indicator. A focus-visible outline is
431	          // drawn INSIDE (negative offset) because the composer clips
432	          // overflow, and the matching radius keeps it hugging the rounded
433	          // box. Mouse clicks are unaffected: focus-visible, not focus.
434	          className="w-full resize-none rounded-[1.6rem] bg-transparent px-6 pb-14 pt-5 text-[15px] leading-relaxed text-neutral-900 outline-none placeholder:text-neutral-500 focus-visible:outline-2 focus-visible:outline-offset-[-3px] focus-visible:outline-[var(--accent)] dark:text-white dark:placeholder:text-neutral-400"
435	        />
436	
437	        <div className="absolute bottom-3 left-3 flex items-center gap-1">
438	          <input ref={fileInputRef} type="file" accept="image/*" className="hidden" onChange={onPickImage} />
439	          <button
440	            type="button"
441	            onClick={() => fileInputRef.current?.click()}
442	            aria-label="Attach an image"
443	            className="flex h-9 w-9 items-center justify-center rounded-full text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
444	          >
445	            <Paperclip size={16} strokeWidth={2} />
446	          </button>
447	          {speechSupported && (
448	            <button
449	              type="button"
450	              onClick={toggleListening}
451	              aria-label={listening ? "Stop voice input" : "Start voice input"}
452	              className={`relative flex h-9 w-9 items-center justify-center rounded-full transition-colors ${
453	                listening
454	                  ? "text-white"
455	                  : "text-neutral-500 hover:bg-black/5 hover:text-neutral-900 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
456	              }`}
457	              style={listening ? { background: "var(--brand-gradient)" } : undefined}
458	            >
459	              {/* Skipped under reduced motion — it's a framer-motion (JS)
460	                  animation, so the CSS-only reduced-motion rule in
461	                  globals.css doesn't reach it. The button's solid gradient
462	                  fill still shows that recording is on. */}
463	              {listening && !reduced && (
464	                <motion.span
465	                  aria-hidden
466	                  className="absolute inset-0 rounded-full"
467	                  style={{ background: "var(--brand-gradient)" }}
468	                  animate={{ opacity: [0.5, 0, 0.5], scale: [1, 1.6, 1] }}
469	                  transition={{ duration: 1.4, repeat: Infinity, ease: "easeInOut" }}
470	                />
471	              )}
472	              <Mic size={16} strokeWidth={2} className="relative" />
473	            </button>
474	          )}
475	          {enhanceSupported && (
476	            <button
477	              type="button"
478	              onClick={enhance}
479	              disabled={enhancing || !value.trim()}
480	              aria-label="Expand this into a fuller spec you can edit"
481	              className="flex h-9 items-center gap-1.5 rounded-full px-3 text-xs font-medium text-neutral-500 transition-colors hover:bg-black/5 hover:text-neutral-900 disabled:pointer-events-none disabled:opacity-40 dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
482	            >
483	              <Sparkles size={14} strokeWidth={2} />
484	              {enhancing ? "Enhancing…" : "Enhance"}
485	            </button>
486	          )}
487	        </div>
488	
489	        <motion.button
490	          type="button"
491	          onClick={submit}
492	          disabled={!value.trim()}
493	          aria-label="Start building"
494	          whileHover={value.trim() ? { scale: 1.06 } : undefined}
495	          whileTap={value.trim() ? { scale: 0.94 } : undefined}
496	          className="absolute bottom-3 right-3 flex h-9 w-9 items-center justify-center rounded-full text-white shadow-[0_6px_18px_-4px_var(--glow)] transition-opacity disabled:opacity-30"
497	          style={{ background: "var(--brand-gradient)" }}
498	        >
499	          <ArrowUp size={16} strokeWidth={2.5} />
500	        </motion.button>
501	      </div>
502	
503	      </div>
504	
505	      <div className="mt-4 flex flex-wrap items-center justify-center gap-2">
506	        {SUGGESTIONS.map((s) => (
507	          <button
508	            key={s}
509	            type="button"
510	            onClick={() => setValue(s)}
