3	import { getCurrentUser } from "@/lib/auth";
4	import { estimateCredits, getBalance, getSpendCapStatus } from "@/lib/credits";
5	import { billingEnabled } from "@/lib/stripe";
6	import { getTemplate } from "@/lib/templates";
7	import { CreateFlow } from "./CreateFlow";
8	
9	export const dynamic = "force-dynamic";
10	
11	export const metadata: Metadata = {
12	  title: "Create a website",
13	};
