15	/* The prompt moment, inside the shell.
16	   ────────────────────────────────────
17	   Deliberately not laid out as a dashboard page: no stat row, no section
18	   headers, no cards full of numbers. One heading, one box, and the honest
19	   price of pressing the button. Everything the customer might reach for
20	   instead — a written brief, the wizard, a reference image — is a quiet
21	   control under the box rather than a competing panel beside it.
22	
23	   `?template=<id>` pre-fills the box from lib/templates.ts. The text is
24	   ordinary editable content once it lands there; nothing about the project
25	   that gets built is different because a template was used. */
26	export default async function CreateWebsitePage({
27	  searchParams,
28	}: {
29	  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
30	}) {
31	  const user = await getCurrentUser();
32	  if (!user) redirect("/login");
33	
34	  const params = await searchParams;
35	  const templateId = typeof params.template === "string" ? params.template : null;
36	  const template = templateId !== null ? getTemplate(templateId) : undefined;
37	
38	  const [balance, cap] = await Promise.all([getBalance(user.id), getSpendCapStatus(user.id)]);
39	
40	  return (
41	    <CreateFlow
42	      initialPrompt={template?.prompt ?? ""}
43	      templateName={template?.name ?? null}
44	      credits={{
45	        balance,
46	        estimate: estimateCredits("create"),
47	        cap: {
48	          cap: cap.cap,
49	          spent: cap.spent,
50	          // `remaining` is Infinity when uncapped, which does not survive the
51	          // server/client boundary as a number worth rendering.
52	          remaining: Number.isFinite(cap.remaining) ? cap.remaining : null,
53	          reached: cap.reached,
54	        },
55	      }}
56	      // Offering "Top up" when Stripe is not configured would be a dead end.
57	      // The billing page is worth reaching either way — it is the credit
58	      // ledger, which is exactly what someone short of credits wants to read.
59	      canTopUp={billingEnabled()}
60	    />
61	  );
62	}
