1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import { Composer, type AttachedImage, type CreditContext } from "./Composer";
6	import { BuildLaunch } from "./BuildLaunch";
7	import {
8	  INITIAL_BUILD,
9	  parseStreamEvent,
10	  reduceBuild,
11	  type BuildProgress,
12	  type BuildSignal,
13	} from "./build-steps";
14	
15	/** Same shape the homepage hand-off uses (lib/pending-prompt.ts) so a project
16	    started here is named the way a project started there is. Reimplemented
17	    rather than imported because that helper is not exported. */
18	function deriveName(prompt: string): string {
19	  const trimmed = prompt.trim().replace(/\s+/g, " ");
20	  return trimmed.length > 60 ? trimmed.slice(0, 57) + "…" : trimmed || "New site";
21	}
22	
23	type Phase = "compose" | "building";
24	
25	export function CreateFlow({
26	  initialPrompt,
27	  templateName,
28	  credits,
29	  canTopUp,
30	}: {
31	  initialPrompt: string;
32	  templateName: string | null;
33	  credits: CreditContext;
34	  canTopUp: boolean;
35	}) {
36	  const router = useRouter();
37	  const [phase, setPhase] = useState<Phase>("compose");
38	  const [prompt, setPrompt] = useState(initialPrompt);
39	  const [image, setImage] = useState<AttachedImage | null>(null);
40	  const [submitted, setSubmitted] = useState("");
41	  const [progress, setProgress] = useState<BuildProgress>(INITIAL_BUILD);
42	  const [projectId, setProjectId] = useState<string | null>(null);
43	  const [stopping, setStopping] = useState(false);
44	  /** True only when the server REFUSED the request with a non-2xx response.
45	      Those paths (kill switch, no credits, spend cap, rate limit) all return
46	      before app/api/generate/route.ts writes a Build row or a user Message, so
47	      the project is still pristine and a retry is genuinely a first build. */
48	  const [retrySafe, setRetrySafe] = useState(false);
49	
50	  const abortRef = useRef<AbortController | null>(null);
51	  const stoppedRef = useRef(false);
52	  /** Mirrors `progress` for the async loop, which cannot read state. */
53	  const stateRef = useRef<BuildProgress>(INITIAL_BUILD);
54	
55	  const running = phase === "building" && progress.outcome === "running";
56	
57	  // Closing or reloading the tab drops the response body, which aborts the
58	  // model request server-side. Warning about it is the honest thing to do —
59	  // the alternative is someone losing a build they were watching.
60	  useEffect(() => {
61	    if (!running) return;
62	    const warn = (e: BeforeUnloadEvent) => e.preventDefault();
63	    window.addEventListener("beforeunload", warn);
64	    return () => window.removeEventListener("beforeunload", warn);
65	  }, [running]);
66	
67	  // Navigating away inside the app (a sidebar link, the back button) unmounts
68	  // this component but does NOT cancel an in-flight fetch — the build would
69	  // keep running for a screen nobody is looking at and then yank the customer
70	  // into the builder from wherever they had gone. Aborting on unmount is what
71	  // makes "leaving stops the build" a true statement rather than a hope, and
72	  // an aborted build is written FAILED with creditsCharged: 0.
73	  //
74	  // Safe on the success path: `run` clears abortRef in its finally block
75	  // before React processes the navigation router.push() schedules.
76	  useEffect(() => () => abortRef.current?.abort(), []);
77	
78	  const signal = useCallback((s: BuildSignal) => {
79	    const next = reduceBuild(stateRef.current, s);
80	    stateRef.current = next;
81	    setProgress(next);
82	    return next;
83	  }, []);
84	
85	  const run = useCallback(
86	    async (text: string, imageDataUrl: string | null, existingProjectId: string | null) => {
87	      stateRef.current = INITIAL_BUILD;
88	      setProgress(INITIAL_BUILD);
89	      setStopping(false);
90	      setRetrySafe(false);
91	      stoppedRef.current = false;
92	      setSubmitted(text);
93	      setPhase("building");
94	
95	      let id = existingProjectId;
96	
97	      // ── 1. The project ───────────────────────────────────────────────────
98	      if (id === null) {
99	        try {
100	          const res = await fetch("/api/projects", {
101	            method: "POST",
102	            headers: { "Content-Type": "application/json" },
103	            body: JSON.stringify({ name: deriveName(text) }),
104	          });
105	          const body: unknown = await res.json().catch(() => null);
106	          const created =
107	            typeof body === "object" && body !== null
108	              ? (body as { project?: { id?: unknown } }).project
109	              : undefined;
110	          if (!res.ok || typeof created?.id !== "string") {
111	            const message =
112	              typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
113	                ? (body as { error: string }).error
114	                : "Your project couldn't be created. Nothing was charged — try again.";
115	            signal({ kind: "failed", message });
116	            setRetrySafe(true);
117	            return;
118	          }
119	          id = created.id;
120	        } catch {
121	          signal({
122	            kind: "failed",
123	            message:
124	              "Your project couldn't be created — the request didn't reach Kodely. Nothing was charged.",
125	          });
126	          setRetrySafe(true);
127	          return;
128	        }
129	        setProjectId(id);
130	      }
131	      signal({ kind: "project-created" });
132	
133	      // ── 2. The build ─────────────────────────────────────────────────────
134	      const controller = new AbortController();
135	      abortRef.current = controller;
136	
137	      try {
138	        const res = await fetch("/api/generate", {
139	          method: "POST",
140	          headers: { "Content-Type": "application/json" },
141	          body: JSON.stringify({ projectId: id, prompt: text, image: imageDataUrl }),
142	          signal: controller.signal,
143	        });
144	
145	        if (!res.ok || !res.body) {
146	          const body: unknown = await res.json().catch(() => null);
147	          const message =
148	            typeof body === "object" && body !== null && typeof (body as { error?: unknown }).error === "string"
149	              ? (body as { error: string }).error
150	              : "The build couldn't be started.";
151	          // A refusal happens before anything is written or charged, so this
152	          // project is still a clean slate.
153	          setRetrySafe(true);
154	          signal({ kind: "failed", message });
155	          return;
156	        }
157	
158	        signal({ kind: "accepted" });
159	
160	        const reader = res.body.getReader();
161	        const decoder = new TextDecoder();
162	        let buffer = "";
163	        let sawTerminal = false;
164	
165	        for (;;) {
166	          const { done, value } = await reader.read();
167	          if (done) break;
168	          buffer += decoder.decode(value, { stream: true });
169	
170	          const frames = buffer.split("\n\n");
171	          buffer = frames.pop() ?? "";
172	
173	          for (const frame of frames) {
174	            if (!frame.startsWith("data: ")) continue;
175	            let raw: unknown;
176	            try {
177	              raw = JSON.parse(frame.slice(6));
178	            } catch {
179	              continue;
180	            }
181	            const event = parseStreamEvent(raw);
182	            if (event === null) continue;
183	            if (event.type === "done" || event.type === "error") sawTerminal = true;
184	            signal({ kind: "sse", event });
185	          }
186	        }
187	
188	        // The route always sends `done` or `error` unless the client went
189	        // away. A stream that ends without either IS a dropped connection —
190	        // saying "finished" here would be the exact lie this screen exists to
191	        // avoid.
192	        if (!sawTerminal) signal({ kind: "lost" });
193	
194	        if (stateRef.current.outcome === "succeeded" && id !== null) {
195	          router.push(`/projects/${id}`);
196	        }
197	      } catch {
198	        if (stoppedRef.current) signal({ kind: "stopped" });
199	        else
200	          signal({
201	            kind: "failed",
202	            message:
203	              "The connection to the build dropped. Nothing was charged — open the project to see what was written.",
204	          });
205	      } finally {
206	        abortRef.current = null;
207	        setStopping(false);
208	      }
209	    },
210	    [router, signal],
211	  );
212	
213	  function stop() {
214	    if (!running || stopping || abortRef.current === null) return;
215	    stoppedRef.current = true;
216	    setStopping(true);
217	    // A real cancel: aborting the fetch closes the response body, which fires
218	    // cancel() on the route's stream and aborts the model request. The Build
219	    // row is written FAILED with creditsCharged: 0.
220	    abortRef.current.abort();
221	  }
222	
223	  if (phase === "building") {
224	    return (
225	      <BuildLaunch
226	        progress={progress}
227	        prompt={submitted}
228	        projectId={projectId}
229	        stopping={stopping}
230	        onStop={stop}
231	        onRetry={
232	          retrySafe && progress.outcome === "failed"
233	            ? () => void run(submitted, image?.dataUrl ?? null, projectId)
234	            : null
235	        }
236	        onEdit={() => {
237	          setPhase("compose");
238	          setProgress(INITIAL_BUILD);
239	          stateRef.current = INITIAL_BUILD;
240	        }}
241	      />
242	    );
243	  }
244	
245	  return (
246	    <Composer
247	      value={prompt}
248	      onChange={setPrompt}
249	      image={image}
250	      onImageChange={setImage}
251	      onSubmit={() => void run(prompt.trim(), image?.dataUrl ?? null, projectId)}
252	      fromTemplate={templateName}
253	      credits={credits}
254	      canTopUp={canTopUp}
255	    />
256	  );
257	}
