45	  const body = (await req.json().catch(() => null)) as {
46	    projectId?: string;
47	    prompt?: string;
48	    image?: string;
49	  } | null;
50	  const prompt = body?.prompt?.trim();
51	  if (!body?.projectId || !prompt) {
52	    return Response.json({ error: "Missing project or prompt." }, { status: 400 });
53	  }
54	
55	  // Only a data: URL (what the client-side downscale in PromptHero produces)
56	  // is accepted — anything else is silently dropped rather than passed on.
57	  const imageMatch = body.image?.match(/^data:(image\/(?:png|jpeg|webp));base64,(.+)$/);
58	  const image = imageMatch ? { mediaType: imageMatch[1], data: imageMatch[2] } : undefined;
59	
60	  const project = await db.project.findFirst({
61	    where: { id: body.projectId, userId: user.id },
62	    include: { messages: { orderBy: { createdAt: "asc" } } },
63	  });
64	  if (!project) return Response.json({ error: "Project not found." }, { status: 404 });
