303	
304	          try {
305	            send({ type: "progress", text: "Compiling the site" });
306	            buildOutput = await buildSite(await readSourceFiles());
307	            break; // compiled cleanly — done
308	          } catch (err) {
309	            lastBuildError = err instanceof BuildError ? err.message : String(err);
310	            if (attempt >= MAX_BUILD_ATTEMPTS) throw new Error(lastBuildError);
311	            repairAttempts++;
312	            // Clear the dedupe key: the repair pass legitimately repeats the
313	            // same lines, and suppressing them would look like a stall.
314	            lastProgress = "";
315	            send({ type: "status", text: "Build didn't compile — fixing it…" });
316	            request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${lastBuildError}`;
317	          }
318	        }
319	
320	        if (abortController.signal.aborted || !buildOutput) {
321	          // Loop ended without a successful build and without throwing —
322	          // only reachable via the abort path (see the `break` above).
323	        } else {
324	          succeeded = true;
325	
326	          // Replace the compiled tree with the new build output.
327	          await db.$transaction([
328	            db.projectFile.deleteMany({ where: { projectId: project.id, published: false, kind: "build" } }),
329	            ...(Object.keys(buildOutput).length > 0
330	              ? [
331	                  db.projectFile.createMany({
332	                    data: Object.entries(buildOutput).map(([path, content]) => ({
333	                      projectId: project.id,
334	                      path,
335	                      content,
336	                      published: false,
337	                      kind: "build",
338	                    })),
339	                  }),
340	                ]
341	              : []),
342	          ]);
343	
344	          // costMicros is the WHOLE run — every attempt, recorded as spent.
345	          // credits is only the customer's own attempt; a repair pass is our
346	          // mistake and our cost. See settleBuild in lib/credits.ts.
347	          const totals = sumUsage(attemptUsage);
348	          const settlement = settleBuild(model, attemptUsage);
349	          const { costMicros: micros, credits } = settlement;
350	          // A zero charge writes no ledger row. The ledger is a financial
351	          // record; an entry that moves nothing is noise in a statement a
352	          // customer may one day be reading to understand their bill.
353	          const remaining =
354	            credits > 0
355	              ? await chargeForBuild(user.id, build.id, credits)
356	              : await getBalance(user.id);
357	
358	          const sourceFiles = await readSourceFiles();
359	          const filesSnapshot = { source: sourceFiles, build: buildOutput };
360	
361	          await db.build.update({
362	            where: { id: build.id },
363	            data: {
364	              status: "SUCCEEDED",
365	              model,
366	              endedAt: new Date(),
367	              ...usageColumns(totals),
368	              filesWritten,
369	              repairAttempts,
370	              costMicros: micros,
371	              creditsCharged: credits,
372	              filesSnapshot,
373	            },
374	          });
375	
376	          track(EVENTS.buildSucceeded, {
377	            userId: user.id,
378	            props: {
379	              buildId: build.id,
380	              projectId: project.id,
381	              kind,
382	              model,
383	              repairAttempts,
384	              filesWritten,
385	              credits,
386	              remaining,
387	              // What rule 4 cost us on this build. Separate from `credits` so
388	              // the absorbed total is measurable without re-deriving it from
389	              // costMicros in every query.
390	              waivedCredits: settlement.waivedCredits,
391	              waivedMicros: settlement.waivedMicros,
392	            },
393	          });
394	
395	          if (lastReply.trim()) {
396	            await db.message.create({
397	              data: { projectId: project.id, role: "assistant", content: lastReply.trim() },
398	            });
399	          }
400	          await db.project.update({ where: { id: project.id }, data: { updatedAt: new Date() } });
401	
402	          // buildId travels to the client so it can attach a rating to this
403	          // specific build (see app/api/feedback/route.ts).
404	          //
405	          // repairWaived/waivedCredits make rule 4 visible instead of a silent
406	          // internal policy. The user watched "Build didn't compile — fixing
407	          // it…" go past; without this the next thing they see is a charge and
408	          // no statement that the fixing part was free. Editor.tsx ignores
409	          // fields it does not know, so it is safe to send today and to render
410	          // whenever that component is updated.
411	          send({
412	            type: "done",
413	            credits,
414	            remaining,
415	            filesWritten,
416	            buildId: build.id,
417	            repairAttempts,
418	            repairWaived: settlement.repairWaived,
419	            waivedCredits: settlement.waivedCredits,
420	          });
421	        }
422	
423	        if (!succeeded) {
424	          const spent = sumUsage(attemptUsage);
425	          await db.build.update({
426	            where: { id: build.id },
427	            data: {
428	              status: "FAILED",
429	              endedAt: new Date(),
430	              error: abortController.signal.aborted ? "Client disconnected." : "Generation ended without producing output.",
431	              filesWritten,
432	              repairAttempts,
433	              creditsCharged: 0,
434	              // Charged zero, but the tokens were still spent. Rule 3 says a
435	              // failed build is "recorded with its true cost and charged
436	              // ZERO"; the recording half was missing, so every failure showed
437	              // $0.0000 in /admin and the give-away figure on
438	              // /admin/analytics was understated by exactly the cost of every
439	              // build that never worked. Under rule 4 that matters more, not
440	              // less: a run that burned two attempts and still failed is the
441	              // most expensive thing we absorb.
442	              ...usageColumns(spent),
443	              costMicros: costMicros(model, spent),
444	              // Record the model on failure too, when we got far enough to
445	              // learn it. It used to be written only on success, so every
446	              // failed build had a blank Model column — which made it
447	              // impossible to attribute a spike in failures to a model change,
448	              // exactly when you most need to.
449	              ...(model ? { model } : {}),
450	            },
451	          });
452	
453	          track(EVENTS.buildFailed, {
454	            userId: user.id,
455	            props: {
456	              buildId: build.id,
457	              projectId: project.id,
458	              kind,
459	              repairAttempts,
460	              reason: abortController.signal.aborted ? "aborted" : "no_output",
461	            },
462	          });
463	        }
464	      } catch (error) {
465	        // A build that fails is never charged — that is the product promise,
466	        // so the ledger is deliberately untouched on this path.
467	        const message =
468	          error instanceof Error ? error.message : "The build failed unexpectedly.";
469	        console.error("[kodely] build failed", build.id, error);
470	
471	        // Same as the other failure path: charged zero, recorded honestly.
472	        const spent = sumUsage(attemptUsage);
473	
474	        await db.build.update({
475	          where: { id: build.id },
476	          data: {
477	            status: "FAILED",
478	            endedAt: new Date(),
479	            error: message.slice(0, 1000),
480	            filesWritten,
481	            repairAttempts,
482	            creditsCharged: 0,
483	            ...usageColumns(spent),
484	            costMicros: costMicros(model, spent),
485	            // See the note on the other failure path — a blank model makes a
486	            // failure impossible to attribute.
487	            ...(model ? { model } : {}),
488	          },
489	        });
490	
491	        track(EVENTS.buildFailed, {
492	          userId: user.id,
493	          props: {
494	            buildId: build.id,
495	            projectId: project.id,
496	            kind,
497	            repairAttempts,
498	            reason: "error",
499	          },
500	        });
501	
502	        send({ type: "error", message });
503	      } finally {
504	        try {
505	          controller.close();
506	        } catch {
507	          // already closed by the client disconnect path
508	        }
509	      }
510	    },
511	    cancel() {
512	      // The client disconnected — stop the in-flight Anthropic request
513	      // rather than let it run to completion for a response nobody reads.
514	      abortController.abort();
515	    },
516	  });
517	
518	  return new Response(stream, {
519	    headers: {
520	      "Content-Type": "text/event-stream; charset=utf-8",
521	      "Cache-Control": "no-cache, no-transform",
522	      Connection: "keep-alive",
523	    },
524	  });
525	}
