1	/**
2	 * Brand kit — a customer's own logo, palette and business name, in a form the
3	 * builder can actually use.
4	 *
5	 * WHY THIS SHAPE, AND NOT A FONT PICKER OR AN UPLOAD BUCKET
6	 * Generated sites are static files served under
7	 *   default-src 'self'; img-src 'self' data:; connect-src 'none'
8	 * with NO font-src (see app/api/site/[slug]/[[...path]]/route.ts). Three
9	 * consequences drive every decision in this file:
10	 *
11	 *  1. There is no remote asset host and no upload CDN, so a logo has to be
12	 *     INLINED — either as SVG markup compiled into a component, or as a data:
13	 *     URI. `img-src` admits `data:`, which is the only reason raster works at all.
14	 *
15	 *  2. Custom web fonts are impossible, base64 included. With no `font-src`,
16	 *     @font-face falls back to `default-src 'self'`, which does NOT admit
17	 *     `data:` the way `img-src` does. A base64 font is blocked exactly like a
18	 *     remote one, so there is deliberately no typography field here. Type is the
19	 *     system stack, as lib/agent.ts already tells the builder.
20	 *
21	 *  3. Everything here passes through the model's context as tokens on every
22	 *     turn of every build, forever — the logo lives in a source file, and
23	 *     lib/agent.ts's describeFiles() dumps the whole source tree into each
24	 *     request. Size is recurring cost, not a one-off. See LOGO_LIMITS below for
25	 *     the arithmetic that sets the caps.
26	 *
27	 * WHERE A BRAND KIT LIVES
28	 * prisma/schema.prisma has no BrandKit model and must not gain one, but
29	 * ProjectFile.content is a plain String and ProjectFile.kind is a plain String
30	 * whose only existing values are "source" and "build". A third value, "brand",
31	 * gives the kit a row of its own that every existing query already ignores:
32	 *   - the agent never sees it (generate reads kind:"source")
33	 *   - it is never served (site/preview read kind:"build")
34	 *   - it is never exported or published
35	 *   - it DOES survive project duplication (POST /api/projects/[id] copies every
36	 *     draft file regardless of kind) and build restore (which only clears the
37	 *     "source" and "build" draft trees) — both of which are the behaviour you want.
38	 */
39	
40	import { GRADIENTS, type GradientPreset } from "./assets/patterns";
41	
42	// ---------------------------------------------------------------------------
43	// Storage contract
44	// ---------------------------------------------------------------------------
45	
46	/** ProjectFile.kind for the row holding the serialised kit. Not "source"/"build". */
47	export const BRAND_FILE_KIND = "brand";
48	/** ProjectFile.path for that row. Never reachable by the agent — see above. */
49	export const BRAND_FILE_PATH = "brand.json";
50	
51	/**
52	 * The generated component the kit compiles the logo into. A real source file so
53	 * the builder can `import { BrandLogo } from "./components/brand/BrandLogo"`
54	 * and place it, rather than being handed raw markup to paste (and mangle).
55	 */
56	export const BRAND_LOGO_COMPONENT_PATH = "src/components/brand/BrandLogo.tsx";
57	/** The stylesheet the @theme block is spliced into. */
58	export const BRAND_CSS_PATH = "src/index.css";
59	
60	// ---------------------------------------------------------------------------
61	// Model
62	// ---------------------------------------------------------------------------
63	
64	export type BrandLogo =
65	  | {
66	      format: "svg";
67	      /** Sanitised markup — output of sanitizeSvg(), never raw upload. */
68	      markup: string;
69	    }
70	  | {
71	      format: "raster";
72	      /** `data:image/png;base64,...` — verified media type and magic bytes. */
73	      dataUri: string;
74	      mediaType: "image/png" | "image/jpeg" | "image/webp";
75	      width: number;
76	      height: number;
77	    };
78	
79	export type BrandPalette = {
80	  /**
81	   * The id of a preset in lib/assets/patterns.ts's GRADIENTS catalogue, or null
82	   * for hand-picked hexes. Sent to the model ALONGSIDE the hexes, never instead
83	   * of them: the id is a stable handle the catalogue already uses everywhere
84	   * else, the hexes are what the site is actually painted with.
85	   */
86	  presetId: string | null;
87	  /** All six are exact `#rrggbb`, lowercase. Never adjectives. */
88	  primary: string;
89	  secondary: string;
90	  accent: string;
91	  /** Body text colour on `surface`. */
92	  ink: string;
93	  /** Page background. */
94	  surface: string;
95	};
96	
97	export type BrandKit = {
98	  version: 1;
99	  businessName: string;
100	  palette: BrandPalette;
101	  logo: BrandLogo | null;
102	  /** ISO timestamp of the last save. */
103	  updatedAt: string;
104	};
105	
106	export const BUSINESS_NAME_MAX = 80;
107	
108	// ---------------------------------------------------------------------------
109	// Size caps, and the arithmetic behind them
110	// ---------------------------------------------------------------------------
111	
112	/**
113	 * TOKEN COST OF A LOGO — the numbers these caps come from.
114	 *
115	 * Base rates. The builder is claude-sonnet-5 at $3 / MTok input
116	 * (lib/models.ts, MODEL_RATES). Base64 of compressed image data is
117	 * high-entropy and tokenises at roughly 3 characters per token; SVG markup,
118	 * with its repeated tag names and digit runs, comes out slightly better at
119	 * roughly 3.2. Both are measured-ballpark, and both are conservative in the
120	 * direction that matters (they under-count tokens, so the real bill is not
121	 * worse than this).
122	 *
123	 * A logo is not paid for once. It lives in a source file, so lib/agent.ts's
124	 * describeFiles() re-sends it in the user message of EVERY turn — and the user
125	 * message is not the cached block (only SYSTEM carries cache_control). A build
126	 * runs up to 8 turns and typically 3-4, and a project has many builds.
127	 * Multiply accordingly: cost = tokens x turns x builds.
128	 *
129	 * The naive option, for scale. A 200 KB PNG dropped in unmodified:
130	 *   200 KB -> ceil(200000/3)*4 = 266,668 base64 chars
131	 *   266,668 / 3 = ~88,900 tokens
132	 *   x $3/MTok = $0.267 per turn -> ~$1.07 over a 4-turn build.
133	 * That is more than the entire rest of the build. Rejected.
134	 *
135	 * SVG cap: 12,288 characters of SANITISED markup (12 KiB).
136	 *   12,288 / 3.2 = ~3,840 tokens -> $0.0115 per turn -> ~$0.046 per 4-turn build.
137	 * Real vector logos land at 1-6 KB after sanitising strips the editor metadata,
138	 * so the cap bites only on auto-traced artwork, which is the case you want to
139	 * refuse anyway. The raw upload is allowed to be 5x that (SVG_RAW_MAX) because
140	 * Illustrator/Inkscape junk is exactly what the sanitiser deletes.
141	 *
142	 * Raster cap: 16,384 characters of data URI (16 KiB).
143	 *   16,384 / 3 = ~5,460 tokens -> $0.0164 per turn -> ~$0.066 per 4-turn build.
144	 * The UI downscales to RASTER_MAX_EDGE = 160 px before encoding, which is what
145	 * makes that cap reachable: a 160 px flat-colour logo PNG is 4-12 KB, i.e.
146	 * 5.3-16 KB of base64. 160 px renders crisply up to ~80 CSS px — a header
147	 * lockup at 2x — and a customer who wants their logo bigger than that wants SVG.
148	 *
149	 * Budget check: a build sends the whole source tree, ~15-25k tokens per turn.
150	 * At 3.8-5.5k tokens the logo is a ~20% surcharge on a first build and less
151	 * afterwards. That is the honest number; it is the price of the feature, and it
152	 * is two orders of magnitude below the naive option.
153	 */
154	export const LOGO_LIMITS = {
155	  /** Hard cap on the raw upload handed to the sanitiser. */
156	  SVG_RAW_MAX: 64 * 1024,
157	  /** Hard cap on the sanitiser's OUTPUT — the thing that actually costs tokens. */
158	  SVG_CLEAN_MAX: 12 * 1024,
159	  /** Hard cap on the whole `data:...` string. */
160	  RASTER_DATA_URI_MAX: 16 * 1024,
161	  /** Longest edge the UI downscales a raster logo to before encoding. */
162	  RASTER_MAX_EDGE: 160,
163	} as const;
164	
165	/** Chars-per-token used above. Exposed so the UI quotes the same number the docs do. */
166	const CHARS_PER_TOKEN = { svg: 3.2, base64: 3 } as const;
167	
168	/** Roughly what this logo adds to every turn of every build. */
169	export function logoTokenEstimate(logo: BrandLogo | null): number {
170	  if (!logo) return 0;
171	  return logo.format === "svg"
172	    ? Math.ceil(logo.markup.length / CHARS_PER_TOKEN.svg)
173	    : Math.ceil(logo.dataUri.length / CHARS_PER_TOKEN.base64);
174	}
175	
176	// ---------------------------------------------------------------------------
177	// Colour
178	// ---------------------------------------------------------------------------
179	
180	/** `#abc`, `abc`, `#AABBCC` -> `#aabbcc`. Null when it is not a hex colour. */
181	export function normalizeHex(raw: unknown): string | null {
182	  if (typeof raw !== "string") return null;
183	  const v = raw.trim().replace(/^#/, "").toLowerCase();
184	  if (/^[0-9a-f]{3}$/.test(v)) return `#${v[0]}${v[0]}${v[1]}${v[1]}${v[2]}${v[2]}`;
185	  if (/^[0-9a-f]{6}$/.test(v)) return `#${v}`;
186	  return null;
187	}
188	
189	function channels(hex: string): [number, number, number] {
190	  return [
191	    parseInt(hex.slice(1, 3), 16),
192	    parseInt(hex.slice(3, 5), 16),
193	    parseInt(hex.slice(5, 7), 16),
194	  ];
195	}
196	
197	function toHex(r: number, g: number, b: number): string {
198	  const clamp = (n: number) => Math.max(0, Math.min(255, Math.round(n)));
199	  return `#${[r, g, b].map((n) => clamp(n).toString(16).padStart(2, "0")).join("")}`;
200	}
201	
202	/** Linear sRGB mix. t=0 returns `a`, t=1 returns `b`. */
203	function mix(a: string, b: string, t: number): string {
204	  const [ar, ag, ab] = channels(a);
205	  const [br, bg, bb] = channels(b);
206	  return toHex(ar + (br - ar) * t, ag + (bg - ag) * t, ab + (bb - ab) * t);
207	}
208	
209	/** WCAG 2.1 relative luminance. */
210	function luminance(hex: string): number {
211	  const [r, g, b] = channels(hex).map((c) => {
212	    const s = c / 255;
213	    return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
214	  });
215	  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
216	}
217	
218	/** WCAG contrast ratio, 1..21. */
219	export function contrastRatio(a: string, b: string): number {
220	  const la = luminance(a);
221	  const lb = luminance(b);
222	  const [hi, lo] = la > lb ? [la, lb] : [lb, la];
223	  return (hi + 0.05) / (lo + 0.05);
224	}
225	
226	const NEAR_BLACK = "#0b1120";
227	const NEAR_WHITE = "#ffffff";
228	
229	/**
230	 * The readable text colour to put ON `bg`. Near-black wins ties, because a
231	 * light-on-mid-tone pairing is the exact failure this codebase already carries
232	 * as a known accepted issue on its own brand gradient — the brand kit must not
233	 * reproduce it on a customer's site.
234	 */
235	export function readableInk(bg: string): string {
236	  const dark = contrastRatio(bg, NEAR_BLACK);
237	  const light = contrastRatio(bg, NEAR_WHITE);
238	  return dark >= light ? NEAR_BLACK : NEAR_WHITE;
239	}
240	
241	/**
242	 * A 50-950 tint/shade ramp anchored so that 500 IS the customer's colour.
243	 * Mixing in sRGB rather than a perceptual space is deliberate: it is
244	 * dependency-free, deterministic, and its output is a family of colours the
245	 * customer can recognise as theirs, which is the whole requirement.
246	 */
247	const RAMP_STEPS: [step: number, toward: "white" | "black", t: number][] = [
248	  [50, "white", 0.95],
249	  [100, "white", 0.9],
250	  [200, "white", 0.78],
251	  [300, "white", 0.62],
252	  [400, "white", 0.35],
253	  [500, "white", 0],
254	  [600, "black", 0.12],
255	  [700, "black", 0.28],
256	  [800, "black", 0.45],
257	  [900, "black", 0.6],
258	  [950, "black", 0.74],
259	];
260	
261	export function colorRamp(base: string): Record<number, string> {
262	  const out: Record<number, string> = {};
263	  for (const [step, toward, t] of RAMP_STEPS) {
264	    out[step] = t === 0 ? base : mix(base, toward === "white" ? NEAR_WHITE : "#000000", t);
265	  }
266	  return out;
267	}
268	
269	// ---------------------------------------------------------------------------
270	// Palette — sourced from the existing catalogue, never a second vocabulary
271	// ---------------------------------------------------------------------------
272	
273	/**
274	 * A catalogue gradient turned into a full palette.
275	 *
276	 * primary/secondary are the gradient's own end stops, so "ocean" here is the
277	 * same ocean the find_assets tool returns to the builder. The accent is derived
278	 * rather than invented: the hue opposite the primary, at the primary's own
279	 * saturation and lightness, which gives a colour that reads as deliberate
280	 * against the pair without introducing a third brand decision the customer
281	 * never made.
282	 */
283	export function paletteFromPreset(presetId: string): BrandPalette | null {
284	  const preset: GradientPreset | undefined = GRADIENTS.find((g) => g.id === presetId);
285	  if (!preset) return null;
286	
287	  const primary = normalizeHex(preset.colors[0]);
288	  const secondary = normalizeHex(preset.colors[preset.colors.length - 1]);
289	  if (!primary || !secondary) return null;
290	
291	  // Three-stop presets (aurora) already ship a middle colour that was chosen to
292	  // sit between the ends; use it rather than computing one.
293	  const middle = preset.colors.length > 2 ? normalizeHex(preset.colors[1]) : null;
294	  const accent = middle ?? complement(primary);
295	
296	  const dark = luminance(primary) < 0.22 && luminance(secondary) < 0.22;
297	  return {
298	    presetId: preset.id,
299	    primary,
300	    secondary,
301	    accent,
302	    // A dark-family preset (midnight, ink, deep-sea) gets a dark surface; every
303	    // other preset stays on near-white, because a mid-tone page background is
304	    // where legibility goes to die.
305	    ink: dark ? "#f8fafc" : NEAR_BLACK,
306	    surface: dark ? "#0b1120" : "#ffffff",
307	  };
308	}
309	
310	function complement(hex: string): string {
311	  const [r, g, b] = channels(hex).map((c) => c / 255);
312	  const max = Math.max(r, g, b);
313	  const min = Math.min(r, g, b);
314	  const l = (max + min) / 2;
315	  const d = max - min;
316	  const s = d === 0 ? 0 : d / (1 - Math.abs(2 * l - 1));
317	  let h = 0;
318	  if (d !== 0) {
319	    if (max === r) h = ((g - b) / d) % 6;
320	    else if (max === g) h = (b - r) / d + 2;
321	    else h = (r - g) / d + 4;
322	  }
323	  h = (h * 60 + 180 + 360) % 360;
324	  return hslToHex(h, s, l);
325	}
326	
327	function hslToHex(h: number, s: number, l: number): string {
328	  const c = (1 - Math.abs(2 * l - 1)) * s;
329	  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
330	  const m = l - c / 2;
331	  const seg = Math.floor(h / 60) % 6;
332	  const rgb: [number, number, number][] = [
333	    [c, x, 0],
334	    [x, c, 0],
335	    [0, c, x],
336	    [0, x, c],
337	    [x, 0, c],
338	    [c, 0, x],
339	  ];
340	  const [r, g, b] = rgb[seg];
341	  return toHex((r + m) * 255, (g + m) * 255, (b + m) * 255);
342	}
343	
344	export type PaletteChoice = {
345	  id: string;
346	  name: string;
347	  family: string;
348	  colors: string[];
349	  css: string;
