1466	        return ` ${toJsxAttr(name)}="${value}"`;
1467	      });
1468	      return `<${tag}${jsxAttrs}${close}>`;
1469	    })
1470	    // Braces in text content would open a JSX expression.
1471	    .replace(/([>])([^<>]*)([<])/g, (_m, a: string, text: string, b: string) =>
1472	      `${a}${text.replace(/[{}]/g, (c) => (c === "{" ? "&#123;" : "&#125;"))}${b}`,
