1476	/**
1477	 * The `src/components/brand/BrandLogo.tsx` the project gets.
1478	 *
1479	 * There is ALWAYS a component, even with no logo uploaded — it falls back to a
1480	 * wordmark in the brand colours. That is not cosmetic: once a generation has
1481	 * written `import { BrandLogo } from ...`, making the file conditional on the
1482	 * logo turns "clear my logo" into a build break on the customer's site.
1483	 */
1484	export function brandLogoComponent(kit: BrandKit): string {
1485	  const name = JSON.stringify(kit.businessName);
1486	  const header = `// Generated by Kodely's brand kit — this is the customer's own logo.
1487	// Do not redraw it, recolour it, or replace it with text. To change it, use the
1488	// Brand panel; editing this file by hand will be overwritten on the next save.
1489	
1490	type Props = { className?: string; title?: string };
1491	`;
1492	
1493	  if (kit.logo?.format === "svg") {
1494	    const jsx = svgToJsx(kit.logo.markup).replace(
1495	      /^<svg /,
1496	      '<svg role="img" aria-label={title} className={className} ',
1497	    );
1498	    return `${header}
1499	export function BrandLogo({ className = "h-8 w-auto", title = ${name} }: Props) {
1500	  return (
1501	    ${jsx}
1502	  );
1503	}
1504	`;
1505	  }
1506	
1507	  if (kit.logo?.format === "raster") {
1508	    const { dataUri, width, height } = kit.logo;
1509	    return `${header}
1510	const SRC =
1511	  "${dataUri}";
1512	
1513	export function BrandLogo({ className = "h-8 w-auto", title = ${name} }: Props) {
1514	  return <img src={SRC} alt={title} width={${width}} height={${height}} className={className} />;
1515	}
1516	`;
1517	  }
1518	
1519	  // The colour is an inline hex rather than `text-brand-700` on purpose: this
1520	  // same fallback is what a CLEARED brand kit leaves behind, and clearing the
1521	  // kit also removes the @theme block that would define that utility. A literal
1522	  // value renders correctly either way.
1523	  const wordmark = colorRamp(kit.palette.primary)[700];
1524	  return `${header}
1525	// No logo file was supplied, so the lockup is a wordmark in the brand colour.
1526	export function BrandLogo({ className = "text-lg font-semibold tracking-tight", title = ${name} }: Props) {
1527	  return (
1528	    <span className={className} style={{ color: "${wordmark}" }}>
1529	      {title}
1530	    </span>
1531	  );
1532	}
1533	`;
1534	}
