1536	// ---------------------------------------------------------------------------
1537	// (b) The prompt fragment
1538	// ---------------------------------------------------------------------------
1539	
1540	/**
1541	 * The instruction the builder is given.
1542	 *
1543	 * Every colour is an exact hex plus, where there is one, the catalogue preset
1544	 * id — never an adjective. "Warm and modern" is precisely what produces the
1545	 * generic template this feature exists to replace, and it is also unfalsifiable:
1546	 * there is no way to check afterwards whether the model honoured it. A hex is
1547	 * checkable, and it is the same hex the @theme block already put in the CSS, so
1548	 * the prompt and the stylesheet cannot drift apart.
1549	 *
1550	 * Measured at ~1,420 characters / ~400 tokens for a preset palette with a logo
1551	 * — about $0.0012 per turn. It rides along on every turn of the build, which is
1552	 * why it is a fixed list of values and not an essay.
1553	 */
1554	export function brandPromptFragment(kit: BrandKit): string {
1555	  const { palette, businessName } = kit;
1556	  const onPrimary = readableInk(palette.primary);
1557	  const primaryVsInk = contrastRatio(palette.primary, onPrimary).toFixed(1);
1558	  const preset = palette.presetId
1559	    ? `catalogue preset "${palette.presetId}"`
1560	    : "custom, chosen by the customer";
1561	
1562	  const logoLine =
1563	    kit.logo === null
1564	      ? `Logo: none supplied. ${BRAND_LOGO_COMPONENT_PATH} exports <BrandLogo /> as a wordmark — use it in the header and footer rather than typing the name again.`
1565	      : `Logo: the customer's real logo is already compiled into ${BRAND_LOGO_COMPONENT_PATH}, which exports <BrandLogo className="h-8 w-auto" />. Import it and place it in the header and the footer. Never redraw it, recolour it, or substitute text for it.`;
1566	
1567	  return [
1568	    "## Brand kit — the customer's actual brand. Not a suggestion, and not a starting point.",
1569	    `Business name: ${JSON.stringify(businessName)}. Use it verbatim in the header, the footer and <title>. Do not translate, abbreviate or restyle it.`,
1570	    `Palette (${preset}) — these exact values are ALREADY seeded as CSS variables in ${BRAND_CSS_PATH}, inside the block marked \`kodely:brand\`. Use the Tailwind utilities, do not re-declare the colours:`,
1571	    `- primary ${palette.primary} — full ramp \`brand-50\`..\`brand-950\` (\`bg-brand-500\`, \`text-brand-700\`, \`border-brand-200\`); ${palette.primary} itself is \`brand-500\`.`,
1572	    `- secondary ${palette.secondary} — \`var(--color-brand-secondary)\`.`,
1573	    `- accent ${palette.accent} — \`bg-accent\`, \`text-accent\`. This is the ONLY accent. Do not introduce another.`,
1574	    `- page: text \`text-ink\` (${palette.ink}) on \`bg-surface\` (${palette.surface}).`,
1575	    `- brand gradient: \`bg-[image:var(--brand-gradient)]\`.`,
1576	    `Contrast: text sitting on ${palette.primary} must be ${onPrimary} — use \`text-brand-contrast\` (${primaryVsInk}:1). Do not put white text on the gradient or on mid-tone brand colours; check every pair you invent.`,
1577	    logoLine,
1578	    "Design freely with these colours — where they go, how much of each, what the layout is. What is fixed is WHICH colours, the name, and the logo.",
1579	  ].join("\n");
1580	}
