1	/**
2	 * Logo handling for the inline wizard.
3	 *
4	 * Deliberately a SIBLING of app/(portal)/dashboard/new/image.ts rather than an
5	 * import of it, for the same reason that file is a copy of the downscale in
6	 * components/marketing/PromptHero.tsx: it belongs to another owner, and the two
7	 * only have to agree about one thing —
8	 *
9	 *     the output must match /^data:image\/(png|jpeg|webp);base64,/
10	 *
11	 * which is the sole gate in app/api/generate/route.ts (line 57). Anything else
12	 * is dropped server-side without a word to the customer, so this module refuses
13	 * it up front instead.
14	 *
15	 * ## Two differences from the reference-image path, both deliberate
16	 *
17	 *  1. PNG out, not JPEG. A logo is the one image that is usually transparent,
18	 *     and JPEG has no alpha — re-encoding one silently paints the transparent
19	 *     area black. PNG keeps it, and `image/png` is on the generate route's
20	 *     accept list, so nothing downstream cares.
21	 *
22	 *  2. A much smaller long edge. This is a brand cue for the model to read, not
23	 *     artwork to reproduce, and every extra kilobyte is base64 in the request.
24	 *     LOGO_MAX_EDGE mirrors the reasoning in lib/brand-kit.ts's LOGO_LIMITS:
25	 *     a flat-colour mark is legible to a vision model far below the size it
26	 *     would need to be printed at.
27	 *
28	 * ## What we do NOT accept
29	 *
30	 * SVG. It has to go through `sanitizeSvg` in lib/brand-kit.ts before it is safe
31	 * to inline anywhere, that function is server-side (it uses node Buffer for the
32	 * raster path and is not built to run here), and the generate route would
33	 * refuse `image/svg+xml` regardless. Offering an SVG picker that silently
34	 * failed later would be exactly the kind of half-working control this product
35	 * is trying to stop shipping.
36	 */
37	
38	/** Exactly what app/api/generate/route.ts will accept as an image. */
39	const ACCEPTED_TYPES = ["image/png", "image/jpeg", "image/webp"] as const;
40	
41	/** Narrower than `image/*` on purpose — a HEIC from a phone would be offered by
42	 *  `image/*` and then fail to decode. */
43	export const LOGO_ACCEPT = ".png,.jpg,.jpeg,.webp,image/png,image/jpeg,image/webp";
44	
45	/** Longest edge after downscaling. See the note above. */
46	export const LOGO_MAX_EDGE = 320;
47	
48	/** Refuse a file this large before decoding it: a 40 MB PNG would be scaled
49	 *  down to the same 320px either way, and decoding it first just freezes the
50	 *  tab on a phone. */
51	const MAX_INPUT_BYTES = 12 * 1024 * 1024;
52	
53	export type LogoResult =
54	  | { ok: true; dataUrl: string; name: string; bytes: number }
55	  | { ok: false; error: string };
56	
57	/**
58	 * Downscale and re-encode a picked file to a PNG data URL.
59	 *
60	 * Re-encoding is what makes the result predictable: whatever came in, what goes
61	 * out is `data:image/png;base64,…`. The prefix is checked rather than assumed,
62	 * because a browser that cannot honour the requested type falls back to PNG
63	 * silently in some engines and to nothing at all in others.
64	 */
65	export async function prepareLogo(file: File): Promise<LogoResult> {
66	  if (!(ACCEPTED_TYPES as readonly string[]).includes(file.type)) {
67	    return {
68	      ok: false,
69	      error: "That file type can't be used. Pick a PNG, JPEG or WebP — SVG isn't supported here.",
70	    };
71	  }
72	  if (file.size > MAX_INPUT_BYTES) {
73	    return {
74	      ok: false,
75	      error: `That file is ${Math.round(file.size / (1024 * 1024))} MB. Export it smaller — a logo never needs more than a megabyte.`,
76	    };
77	  }
78	
79	  try {
80	    const bitmap = await createImageBitmap(file);
81	    const scale = Math.min(1, LOGO_MAX_EDGE / Math.max(bitmap.width, bitmap.height));
82	    const w = Math.max(1, Math.round(bitmap.width * scale));
83	    const h = Math.max(1, Math.round(bitmap.height * scale));
84	
85	    const canvas = document.createElement("canvas");
86	    canvas.width = w;
87	    canvas.height = h;
88	    const ctx = canvas.getContext("2d");
89	    if (!ctx) {
90	      bitmap.close();
91	      return { ok: false, error: "This browser couldn't read that image." };
92	    }
93	    // No fill first: the canvas starts fully transparent, which is what keeps a
94	    // transparent logo transparent all the way into the PNG.
95	    ctx.drawImage(bitmap, 0, 0, w, h);
96	    bitmap.close();
97	
98	    const dataUrl = canvas.toDataURL("image/png");
99	    const PREFIX = "data:image/png;base64,";
100	    if (!dataUrl.startsWith(PREFIX)) {
101	      return { ok: false, error: "This browser couldn't re-encode that image." };
102	    }
103	    return {
104	      ok: true,
105	      dataUrl,
106	      name: file.name,
107	      bytes: Math.round((dataUrl.length - PREFIX.length) * 0.75),
108	    };
109	  } catch {
110	    return { ok: false, error: "That image couldn't be read. Try a different file." };
111	  }
112	}
